/**
 * The contract `switch.tsx` (native) and `switch.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./switch` to
 * `switch.web.tsx` on web — the web file would otherwise import itself.
 *
 * Controlled or not, as radix's is. The web half takes radix's whole
 * `Switch.Root` surface on top of this — `name`, `value`, `required`, the
 * `aria-*` props, shadcn's `size` — because it installs over a DOM app's
 * shadcn switch; this is the part that means something on both platforms.
 */
import type { TooltipSide } from "@/components/ui/tooltip-base";

export type SwitchProps = {
  checked?: boolean | undefined;
  /** Where an uncontrolled switch starts. Ignored once `checked` is passed. */
  defaultChecked?: boolean | undefined;
  onCheckedChange?: ((checked: boolean) => void) | undefined;
  /** Web only: what a `<label htmlFor>` points at. */
  id?: string | undefined;
  disabled?: boolean | undefined;
  /** See `checkbox-base.ts`: a bound field marks itself touched from this. */
  onBlur?: (() => void) | undefined;
  /**
   * The switch's name, as `aria-label`. What names it on device, where there is no
   * `<label htmlFor>` to borrow one from; on the web a label pointed at `id` can do it instead.
   */
  accessibilityLabel?: string | undefined;
  /**
   * The name by reference: the id of visible text that names the switch, such as a `SettingRow`'s
   * title. The web honours it, Android reads it, iOS does not — a native caller that needs the
   * name on an iPhone passes `accessibilityLabel` too.
   */
  "aria-labelledby"?: string | undefined;
  /**
   * What says more about the switch — a `SwitchField`'s `description` — by id. Web only: React
   * Native has no description relation, so on device the line is read where it is drawn.
   */
  "aria-describedby"?: string | undefined;
  /**
   * The value was refused: a validator's error. The track's edge turns `negative`, over the
   * `active` edge of an on switch. A bound field sets it.
   */
  "aria-invalid"?: boolean | "true" | "false" | undefined;
  /**
   * The switch's tooltip, as on `Button`: shown on hover and focus on the web and on a long press on
   * device, and the switch's description. With it, `disabled` keeps the switch focusable and
   * refuses the press (`aria-disabled`), so the reason it cannot be changed can still be read —
   * "Turn the task on first".
   */
  hint?: string | undefined;
  /** Which edge of the switch the tooltip sits on. The default is `top`. */
  side?: TooltipSide | undefined;
  className?: string | undefined;
};

/**
 * Shared between the two files so the track cannot drift between platforms. No shadow: the track
 * sits in the page's flow, and only what floats draws one.
 */
export const SWITCH_TRACK_CLASS =
  "h-5 w-9 shrink-0 flex-row items-center rounded-full border-2 border-transparent";
/**
 * An on switch's track: the chosen tint, edged in `active` because the tint is not 3:1 from the
 * surface, and a step further under the pointer and focused.
 */
export const SWITCH_TRACK_ON_CLASS =
  "border-active bg-active/40 hover:bg-active/60 focus-visible:bg-active/60";
/**
 * An off switch's track: the `/50` grey a control's edge is, 3:1 on every surface. Under the
 * pointer and focused it keeps that fill and is edged in `active`: `bg-hover` in its place took
 * the 3:1 away, and the track all but vanished when tabbed to.
 */
export const SWITCH_TRACK_OFF_CLASS =
  "bg-foreground/50 hover:border-active focus-visible:border-active";
/**
 * The switch's thumb: the circle that slides along the track. The one part laid over another, so
 * the smallest shadow — not a dialog's `shadow-lg`. Off, it is `background` on the `/50` track; on,
 * it is `foreground`, as a chosen thing's mark is, because `background` on the tint is under 3:1.
 */
export const SWITCH_THUMB_CLASS = "h-4 w-4 rounded-full shadow-sm";

/**
 * Copied from `registry/ui/switch.web.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * This is level 4 of the plan: the item has a hand-written web half, so nothing was generated. The
 * same passes still ran over it, and for a file already written against the DOM they find nothing
 * to do beyond pointing its sibling imports at the web tree. That is deliberate — running one
 * pipeline over the whole output tree is what guarantees a hand-written half and a compiled one
 * speak the same prop vocabulary, instead of the two drifting where nobody is looking.
 */

/**
 * The web switch: radix. `switch.tsx` is the native counterpart and
 * `switch-base.ts` holds the contract they share.
 *
 * It takes radix's `Switch.Root` props whole, plus shadcn's `size`, because it
 * installs over a DOM app's shadcn switch at `components/ui/switch.tsx`:
 * `defaultChecked`, `name`, `value`, `required` and the `aria-*` props all
 * reach radix, which renders the hidden `<input>` a native form submit reads.
 */

import { Switch as SwitchPrimitive } from "radix-ui";
import { type ComponentPropsWithRef, useId } from "react";
import { SWITCH_THUMB_CLASS, SWITCH_TRACK_CLASS } from "@/components/ui/switch-base";
import type { TooltipSide } from "@/components/ui/tooltip-base";
import { cn } from "@/lib/utils";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

export type SwitchProps = Omit<ComponentPropsWithRef<typeof SwitchPrimitive.Root>, "className"> & {
  className?: string | undefined;
  /** shadcn's smaller track. Web only; the native switch is one size. */
  size?: "sm" | "default" | undefined;
  /**
   * The device half's name for the switch, taken so a call site shared across both halves still
   * names it — see `checkbox.web.tsx`. It becomes `aria-label`; an `aria-label` of its own wins.
   */
  accessibilityLabel?: string | undefined;
  /**
   * The switch's tooltip and description, as on `Button`. With it, `disabled` keeps the switch
   * focusable and refuses the press (`aria-disabled`), so the reason can still be read.
   */
  hint?: string | undefined;
  /** Which edge of the switch the tooltip sits on. The default is `top`. */
  side?: TooltipSide | undefined;
};

/** A control that is on or off. */
function Switch({
  className,
  size = "default",
  accessibilityLabel,
  "aria-label": ariaLabel,
  hint,
  side = "top",
  disabled,
  onClick,
  "aria-describedby": ariaDescribedBy,
  ...props
}: SwitchProps) {
  const hintId = useId();
  const hasHint = Boolean(hint);
  // As on `Button`: with a hint, a disabled switch keeps its focus and tooltip and refuses the press.
  const refuses = hasHint && Boolean(disabled);
  const describedBy = [ariaDescribedBy, hasHint ? hintId : undefined].filter(Boolean).join(" ");

  const root = (
    <SwitchPrimitive.Root
      data-slot="switch"
      data-size={size}
      {...props}
      disabled={refuses ? false : disabled}
      {...(refuses ? { "aria-disabled": true } : {})}
      {...(describedBy === "" ? {} : { "aria-describedby": describedBy })}
      onClick={(event) => {
        onClick?.(event);
        // Radix skips its toggle for a click whose default is prevented.
        if (refuses) {
          event.preventDefault();
        }
      }}
      aria-label={ariaLabel ?? accessibilityLabel}
      className={cn(
        SWITCH_TRACK_CLASS,
        // On, `SWITCH_TRACK_ON_CLASS` under `data-[state=checked]:`, and off `SWITCH_TRACK_OFF_CLASS`
        // under `data-[state=unchecked]:`. Invalid is stacked on the on state as well: a
        // `data-[state]:` edge is emitted after an `aria-invalid:` one and would win, hiding a
        // refused on switch. An off one's `active` edge under the pointer and focused does win, as a
        // refused field's does, so it still shows where focus is.
        "peer group/switch inline-flex cursor-pointer transition-colors focus-visible:outline-none data-[state=unchecked]:hover:border-active data-[state=unchecked]:focus-visible:border-active data-[state=checked]:border-active data-[state=checked]:bg-active/40 data-[state=checked]:hover:bg-active/60 data-[state=checked]:focus-visible:bg-active/60 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-negative aria-invalid:data-[state=checked]:border-negative data-[state=unchecked]:bg-foreground/50 data-[size=sm]:h-4 data-[size=sm]:w-7",
        refuses && "cursor-not-allowed opacity-50",
        className,
      )}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          SWITCH_THUMB_CLASS,
          "pointer-events-none block ring-0 transition-transform motion-reduce:transition-none data-[state=checked]:bg-foreground data-[state=unchecked]:bg-background data-[state=checked]:translate-x-4 data-[state=unchecked]:translate-x-0 group-data-[size=sm]/switch:h-3 group-data-[size=sm]/switch:w-3 group-data-[size=sm]/switch:data-[state=checked]:translate-x-3",
        )}
      />
    </SwitchPrimitive.Root>
  );

  if (hasHint === false) {
    return root;
  }
  return (
    <>
      <Tooltip>
        <TooltipTrigger asChild>{root}</TooltipTrigger>
        <TooltipContent side={side}>{hint}</TooltipContent>
      </Tooltip>
      <span id={hintId} className="sr-only">
        {hint}
      </span>
    </>
  );
}

export { Switch };
